WITH rollup_totals AS (SELECT d.segment, d.city, a.status, COUNT(*) AS cnt, MAX(a.monthly_fee) AS max_monthly_fee, GROUPING_ID() AS gid FROM subscriptions a LEFT JOIN customers d ON a.customer_id = d.id GROUP BY ROLLUP (d.segment, d.city, a.status)) SELECT segment, status, cnt, max_monthly_fee, CASE WHEN segment RLIKE '^(SMB|Corporate)$' THEN 'EXTENDED' WHEN segment RLIKE '^(Consumer)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS segment_zone FROM rollup_totals ORDER BY segment DESC NULLS LAST;
